import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.component.html',
  styleUrls: ['./reset-password.component.css']
})
export class ResetPasswordComponent {

  public form: FormGroup;

  constructor(
    private fb: FormBuilder,
    private router: Router)
  {
    this.form = this.fb.group({
      email: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(150),
          Validators.required
        ])
      ],
    })
  }

  reset(){
    
  }
}
<div class="uk-flex-center" uk-grid>
  <div class="uk-width-1-3@m">
    <p class="uk-text-center uk-margin-large-top uk-margin-medium-bottom">
      <span>
        <img src="assets/images/ifood-43.png" style="width: 10%; height: 10%;">
      </span>
    </p>


    <form>
      <div class="uk-card uk-card-primary uk-card-body uk-box-shadow-small" id="reset-color">
        <h3 class="uk-card-title">Restaurar Senha</h3>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="email" type="email" placeholder="Email">
        </div>

        <div class="uk-margin uk-text-right">
          <button class="uk-button uk-button-default" id="button-reset" (click)="reset()">Restaurar</button>
        </div>

      </div>
    </form>

    <p class="uk-text-center">
      <a [routerLink]="['/login']" class="uk-button uk-button-link">Cancelar</a>
    </p>

  </div>
</div>
